static void dev_draw(const DeveloperUI*u,const Combat*g){
 static const char*tabs[5]={"Player build","Practice","Classes","Items","Rates"};ui_panel(68,48,504,390,"Developer testing - paused",0,-1);
 for(int i=0;i<5;i++){ui_cell(80+i*97,80,93,24,u->tab==i);ui_scaled(85+i*97,84,.85f,"%s",tabs[i]);}
 if(u->confirm){ui_text(92,142,"Confirm %s?",u->confirm==1?"levels and full build reset":u->confirm==2?"stat reset":"skill reset");ui_text(92,172,"Spent points will be refunded. Items are kept.");ui_text(92,204,"Cleared skill bindings must be assigned again.");ui_text(92,246,"A: confirm     B: cancel");}
 else if(u->tab==3){int count=dev_item_count52(u->itemGroup),start=u->row/7*7;ui_text(90,118,"< %s >  %d / %d",devItemGroups52[u->itemGroup],u->row+1,count);for(int row=start;row<count&&row<start+7;row++){int item=dev_item_row52(u->itemGroup,row);ui_cell(80,145+(row-start)*22,480,22,row==u->row);ui_scaled(90,148+(row-start)*22,.85f,"%u  %.48s",itemDefs[item].id,itemDefs[item].name);}ui_hint64(88,303,.8f,"X/Y: jump 7   Black: quantity %d   A: add",u->itemQuantity);}
 else for(int i=u->tab==2?u->row/7*7:0;i<(u->tab==2?devClassCounts48[u->classGroup]:dev_rows(u->tab))&&(u->tab!=2||i<u->row/7*7+7);i++){char row[100];if(u->tab==0){if(i==0)snprintf(row,sizeof(row),"Base level: %d  (left/right; cap %d)",u->base,TEST_LEVEL_CAP);else if(i==1)snprintf(row,sizeof(row),"Job level: %d  (left/right; cap %d)",u->job,job_cap(g));else if(i==8)snprintf(row,sizeof(row),"Gender: %s (A / left / right)",g->sex55?"Male":"Female");else if(i==7)snprintf(row,sizeof(row),"Peco mount: %s (Knight / Crusader)",g->mounted48?"Riding":"Dismounted");else if(i==6)snprintf(row,sizeof(row),"Walking pace: %d%% (L/R adjust; A resets100%%)",g->walkPercent);else {static const char*label[4]={"Apply levels + reset stats and skills...","Restore HP / SP; cure poison","Reset stats and refund points...","Reset learned skills and refund points..."};snprintf(row,sizeof(row),"%s",label[i-2]);}}
 else if(u->tab==1){if(i==0)snprintf(row,sizeof(row),"Species: %s  (left/right)",mobSpecs[u->species].name);else if(i==1)snprintf(row,sizeof(row),"Target HP: x%d  (cap 1,000,000)",u->scale==0?1:u->scale==1?10:u->scale==2?100:1000);else if(i==2)snprintf(row,sizeof(row),"Practice target cannot die: %s",g->debugImmortal?"On":"Off");else if(i==3)snprintf(row,sizeof(row),"Spawn / replace passive practice target");else if(i==4)snprintf(row,sizeof(row),"Remove practice target");else if(i==5)snprintf(row,sizeof(row),"Other monster AI: %s",g->debugFreeze?"Paused":"Normal");else if(i==6)snprintf(row,sizeof(row),"Toggle practice target hidden / visible");else if(i==10)snprintf(row,sizeof(row),"Queue practice Fire Bolt (3s after resume)");else if(i==9){static const char*ailments[3]={"Blind","Silence","Confusion"};snprintf(row,sizeof(row),"Apply ailment: %s (L/R choose; A apply)",ailments[u->ailment]);}else if(i==8)snprintf(row,sizeof(row),"Practice behaviour: %s (A/L/R toggle)",g->mobs[MOB_COUNT-1].trainingActive?"Active":"Idle");else {static const char*types[4]={"Natural","Demon TEST","Undead TEST","Boss immunity TEST"};snprintf(row,sizeof(row),"Target type: %s (left/right or A)",types[g->mobs[MOB_COUNT-1].testTraits]);}}
 else if(u->tab==4){static const char*labels[6]={"Base EXP at Lv90+","Job EXP at Lv90+","Common drops","Equipment drops","Normal cards","MVP cards"};unsigned rate=gameRates164[i];snprintf(row,sizeof(row),"%s: %u.%ux",labels[i],rate/10,rate%10);}
 else if(u->tab==2)snprintf(row,sizeof(row),"Max test build: %s",job_name(devClassIDs48[u->classGroup][i]));
 int step=u->tab==1?17:u->tab==0?22:24,groupOffset=u->tab==2?28:0;ui_cell(80,117+groupOffset+(u->tab==2?i%7:i)*step,480,step,i==u->row);ui_scaled(90,120+groupOffset+(u->tab==2?i%7:i)*step,u->tab==1?.85f:1.f,"%s",row);}
 if(u->tab==2&&!u->confirm){ui_text(90,118,"< %s >  (left/right)",devClassGroups48[u->classGroup]);if(devClassCounts48[u->classGroup]>7)ui_text(468,118,"%d / %d",u->row/7+1,(devClassCounts48[u->classGroup]+6)/7);}
 if(u->tab==4&&!u->confirm){ui_scaled(90,282,.85f,"EXP scales from 1x at Lv1 to the chosen rate at Lv90.");ui_scaled(90,303,.85f,"Drops use flat rates. LEFT/RIGHT: 0.5x; A: reset default.");}
 /* Footer has its own reserved region below every tab's final row. */
 pb_fill(80,329,480,101,0xffeaf0f5);pb_fill(80,329,480,1,0xff8999b2);
 ui_hint64(88,337,.85f,"LT/RT: tab   D-pad / sticks: choose/adjust   A: select");
 ui_hint64(88,355,.85f,"B: back   START: resume   Practice settings: session only");
 ui_fit47(88,389,464,.85f,u->status);char summary[160];snprintf(summary,sizeof(summary),"%s | Level %d / Job %d | Free build points: %d / %d",job_name(g->jobId),g->level,g->joblevel,g->statPoints,g->skillPoints);ui_fit47(88,412,464,.85f,summary);
}
